d.Htau=D("H_tau","cubic increment, for positive tau and L2 inputs",range(52,55),[d.Ftau,d.S,d.P,d.P0,d.Dinv,d.Dinv2],["F_tau","S","P","P0","Dinv","Dinv2"],[{symbol:"tau",type:"positive real"},{symbol:"f",type:"L2 function"},{symbol:"s",type:"endpoint bracket variable taking values 0,tau"}]);
